from pathlib import Path
import json,base64,shutil
R=Path(__file__).resolve().parent
C=json.loads((R/'project.json').read_text());hero='data:image/jpeg;base64,'+base64.b64encode((R/'assets/hero.jpg').read_bytes()).decode();style=(R/'frontend/style.css').read_text()+':root{--hero:url("'+hero+'")}';common=(R/'frontend/common.js').read_text();name=C['name'];flood=C['flood'];kind='flood' if flood else 'bio'
def t(en,bn,tag='span',cls=''):return f'<{tag} class="{cls}" data-en="{en}" data-bn="{bn}">{en}</{tag}>'
def ico(n):return f'<span data-icon="{n}"></span>'
def btn(en,bn,url,secondary=False):return f'<a class="btn {"secondary" if secondary else ""}" href="{url}">{t(en,bn)}{ico("arrow")}</a>'
def brand():return f'<a class="brand" href="index.html"><span class="brand-mark">{ico("rain" if flood else "dna")}</span>{name}</a>'
def head(title,desc):return f'<!doctype html><html lang="en" data-backend="0"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | {name}</title><meta name="description" content="{desc}"><meta property="og:title" content="{name}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:image" content="assets/hero.jpg"><meta name="theme-color" content="#090d1a"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 32 32%27%3E%3Crect width=%2732%27 height=%2732%27 rx=%278%27 fill=%27%230d2035%27/%3E%3Ctext x=%2716%27 y=%2723%27 text-anchor=%27middle%27 font-size=%2723%27 fill=%27%2367e8f9%27%3E{ 'B' if flood else 'V' }%3C/text%3E%3C/svg%3E"><style>{style}</style></head>'
def script(s):return '<script>'+s.replace('</script','<\\/script')+'</script>'
def end(extra=''):return '<div id="toast" class="toast hidden" role="status"></div>'+script(common)+script(extra)+'</body></html>'
nav=f'<div class="wrap"><nav class="topnav" aria-label="Main navigation">{brand()}<div class="links"><a href="#explore">{t("Explore","দেখুন")}</a><a href="#how">{t("How it works","কাজের ধাপ")}</a><a href="dashboard.html#methods">{t("Sources &amp; methods","উৎস ও পদ্ধতি")}</a></div><div class="actions"><button class="lang" data-lang>বাংলা</button><a class="btn secondary small" href="login.html">{t("Sign in","সাইন ইন")}</a></div></nav></div>'
herohtml=f'<section class="hero"><div class="wrap" style="width:100%"><div class="hero-inner"><div class="eyebrow"><span class="pulse"></span>{t(C["eyebrow"],C["eyebrow_bn"])}</div><h1>{t(C["headline"],C["headline_bn"])}<br><span class="gradient">{t(C["headline2"],C["headline2_bn"])}</span></h1><p>{t(C["description"],C["description_bn"])}</p><div class="actions">{btn("Enter workspace","ড্যাশবোর্ড খুলুন","login.html")}{btn("Explore as guest","Guest হিসেবে দেখুন","dashboard.html",True)}</div><div class="hero-note">{ico("shield")} {t(C["hero_note"],C["hero_note_bn"])}</div></div><div class="hero-orbit"><span class="tag">{t("Source-aware by design","উৎস আগে, সিদ্ধান্ত পরে")}</span><strong>{t(C["orbit"],C["orbit_bn"])}</strong><p>{t("Every insight has a boundary. Every source stays visible.","প্রতিটি ফলের সীমা ও উৎস সামনে থাকে।")}</p></div></div></section>'
trust='<div class="wrap"><div class="trustbar">'+''.join('<div>'+t(a,b)+f'<strong>{t(c,d)}</strong></div>' for a,b,c,d in C['trust'])+'</div></div>'
features='<section class="section" id="explore"><div class="wrap"><div class="section-head"><div><div class="eyebrow">'+t('A clearer research workflow','গবেষণার সহজ পথ')+'</div><h2>'+t(C['section_title'],C['section_title_bn'])+'</h2></div><p>'+t('Useful tools. Traceable inputs. No invented certainty.','কাজের tool, যাচাইযোগ্য input, আর সীমাবদ্ধতা পরিষ্কার।')+'</p></div><div class="cards3">'+''.join(f'<article class="feature"><span class="symbol">{ico(a)}</span><h3>{t(b,c)}</h3><p>{t(d,e)}</p><a href="dashboard.html#{f}" class="text-btn">{t("Explore feature","ফিচারটি দেখুন")}{ico("arrow")}</a></article>' for a,b,c,d,e,f in C['features'])+'</div></div></section>'
process='<section class="section" id="how" style="padding-top:20px"><div class="wrap"><div class="section-head"><div><div class="eyebrow">'+t('From question to context','প্রশ্ন থেকে প্রমাণ')+'</div><h2>'+t('A thoughtful path through the data.','Data বোঝার ধাপগুলো।')+'</h2></div></div><div class="process">'+''.join(f'<article><b>0{i+1}</b><h3>{t(a,b)}</h3><p>{t(c,d)}</p></article>' for i,(a,b,c,d) in enumerate(C['steps']))+'</div></div></section>'
closing=f'<div class="wrap"><section class="closing"><div class="eyebrow">{t("Built for learning. Designed with care.","শেখার জন্য, যত্ন নিয়ে তৈরি।")}</div><h2>{t(C["closing"],C["closing_bn"])}</h2><p>{t(C["disclaimer"],C["disclaimer_bn"])}</p><div class="actions">{btn("Open the dashboard","ড্যাশবোর্ডে যান","dashboard.html")}{btn("Project source ZIP","Project source ZIP","downloads/"+C["zip"],True)}</div></section><footer class="foot"><span>{name} · {t("Created by Nafisa Tasneem Esha","তৈরি করেছেন Nafisa Tasneem Esha")}</span><span>{t("Decorative AI-generated artwork. Not a real event or scientific figure.","ছবিটি AI-generated সাজসজ্জা; বাস্তব ঘটনা বা scientific figure নয়।")}</span></footer></div>'
welcome=head('Welcome',C['description'])+f'<body class="{kind}">'+nav+herohtml+trust+features+process+closing+end()
outputs={'index.html':welcome}
for mode in ['login','signup']:
 signup=mode=='signup';fields=f'<label class="field">{t("Username","ইউজারনেম")}<input id="username" name="username" minlength="3" maxlength="40" required autocomplete="username"></label><label class="field">{t("Password","পাসওয়ার্ড")}<input id="password" type="password" name="password" minlength="12" maxlength="128" required autocomplete="{"new-password" if signup else "current-password"}"></label>'
 if signup:fields+=f'<label class="field">{t("Confirm password","আবার পাসওয়ার্ড")}<input id="confirm" type="password" required autocomplete="new-password"></label><label class="checkbox-row"><input id="accept" type="checkbox" required>{t("I understand this is a research prototype and will not enter private health or genome data.","এটি research prototype; ব্যক্তিগত স্বাস্থ্য বা genome data দেব না।")}</label>'
 outputs[mode+'.html']=head('Create account' if signup else 'Sign in',C['description'])+f'<body class="{kind}" data-mode="{mode}"><main class="auth-layout"><section class="auth-art">{brand()}<div class="auth-message"><div class="eyebrow">{t(C["eyebrow"],C["eyebrow_bn"])}</div><h1>{t(C["auth_title"],C["auth_title_bn"])}</h1><p>{t(C["description"],C["description_bn"])}</p></div><p class="auth-bottom">{t(C["disclaimer"],C["disclaimer_bn"])}</p></section><section class="auth-main"><div class="auth-card"><div class="actions" style="justify-content:flex-end;margin-bottom:22px"><button class="lang" data-lang>বাংলা</button></div><span class="tag purple">{t("Your research workspace","আপনার research workspace")}</span><h1 style="margin-top:23px">{t("Create an account" if signup else "Welcome back", "অ্যাকাউন্ট খুলুন" if signup else "স্বাগতম")}</h1><p>{t("A place to explore evidence with context.","প্রমাণ পড়ুন, সীমাবদ্ধতা বুঝুন।")}</p><div id="previewNote" class="status-banner warning">{t("Public demo: account forms are disabled. Continue as guest. Real sign-up/sign-in works when you run the included FastAPI server.","Public demo-তে account form বন্ধ। Guest হিসেবে ঢুকুন। ZIP-এর FastAPI server চালালে আসল sign-up/sign-in কাজ করে।")}</div><form id="authForm">{fields}<div class="auth-error" id="authError" role="alert"></div><button id="submitButton" class="btn" type="submit">{t("Create account" if signup else "Sign in", "অ্যাকাউন্ট তৈরি করুন" if signup else "সাইন ইন")}{ico("arrow")}</button></form><div class="separator">{t("or continue without an account","অ্যাকাউন্ট ছাড়াই দেখুন")}</div>{btn("Explore as guest","Guest হিসেবে দেখুন","dashboard.html",True)}<p style="text-align:center;margin-top:22px;font-size:11px"><a class="text-btn" href="{"login" if signup else "signup"}.html">{t("Already registered? Sign in" if signup else "New here? Create an account","অ্যাকাউন্ট আছে? সাইন ইন করুন" if signup else "নতুন? অ্যাকাউন্ট খুলুন")}</a></p><a href="index.html" class="back-home">← {t("Back to welcome","Welcome page-এ ফিরুন")}</a></div></section></main>'+end((R/'frontend/auth.js').read_text())
navitems=''.join(f'<button class="navitem" data-view="{v}">{ico(i)}{t(a,b)}</button>' for v,i,a,b in C['nav'])
sidebar=f'<aside class="sidebar" id="sidebar">{brand()}<div class="nav-caption">{t("WORKSPACE","WORKSPACE")}</div>{navitems}<div class="sidebar-bottom"><a class="navitem" href="downloads/{C["zip"]}">{ico("download")}{t("Project source","Project source")}</a><div class="userline"><span class="avatar">N</span><div><strong id="accountName">{t("Guest researcher","Guest researcher")}</strong><div class="muted">{t("Research edition","Research edition")}</div></div></div><button class="navitem" id="accountAction">{ico("user")}{t("Sign in","সাইন ইন")}</button></div></aside><div id="backdrop" class="mobile-backdrop"></div>'
appbar=f'<header class="appbar"><div class="row"><button id="menuButton" class="btn secondary small desktop-hide" aria-label="Open navigation">{ico("menu")}</button><span class="muted">{name} / {t("Research workspace","Research workspace")}</span></div><div class="actions"><span class="tag">{t("SOURCE-LINKED SNAPSHOT","উৎসসহ snapshot")}</span><button class="lang" data-lang>বাংলা</button><a href="index.html" class="text-btn" aria-label="Welcome page">{ico("home")}</a></div></header><div class="app-title"><div><h1 id="pageTitle">{t("Research dashboard","Research dashboard")}</h1><p id="pageSubtitle">{t(C["dash_sub"],C["dash_sub_bn"])}</p></div><button class="btn secondary small" id="exportPdf">{ico("download")}{t("Export PDF","PDF নিন")}</button></div>'
data=json.loads((R/'data/workspace.json').read_text());datahtml='<script type="application/json" id="dataset">'+json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script>'
extra=''
if (R/'data/experiment.json').exists():extra='<script type="application/json" id="experimentData">'+(R/'data/experiment.json').read_text().replace('<','\\u003c')+'</script>'
app=(R/'frontend/engine.js').read_text()+'\n'+(R/'frontend/app.js').read_text();body=(R/'frontend/dashboard-body.html').read_text()
mobile='<nav class="mobilebar" aria-label="Mobile navigation">'+''.join(f'<button data-view="{v}">{ico(i)}{t(a,b)}</button>' for v,i,a,b in [C['nav'][0],C['nav'][1],C['nav'][4 if flood else 3]])+f'<button id="mobileMore" aria-label="More navigation">{ico("menu")}{t("More","আরও")}</button></nav>'
outputs['dashboard.html']=head('Dashboard',C['description'])+f'<body class="{kind}">'+sidebar+'<main class="workspace">'+appbar+body+'</main>'+mobile+datahtml+extra+end(app)
(R/'dist').mkdir(exist_ok=True)
for n,s in outputs.items():(R/n).write_text(s);(R/'dist'/n).write_text(s)
shutil.copytree(R/'assets',R/'dist/assets',dirs_exist_ok=True)
if (R/'downloads').exists():shutil.copytree(R/'downloads',R/'dist/downloads',dirs_exist_ok=True)
print(name,[(n,len(s)) for n,s in outputs.items()])
